/**
 * Fetch and cache original street JSON from assets/streets/.
 * Index is generated by scripts/import-locations-xml.mjs from locations-xml.
 */

import { assertStreetGeometry, navigableSignposts } from './street-model.js?v=23b926e5';
import { isSolo, resolveGameMode } from './game-mode.js?v=1ecf2899';
import { withoutZoneRows, withoutZoneConnects } from './zone-streets.js?v=b40010d5';

const cache = new Map();

/**
 * LEVEL BUILDER play-test (spec 6.8, js/builder/draft-play.js): a draft's streets, which are not
 * files. Their index rows are merged into STREET_INDEX (and again after any later index load), and
 * their JSON is kept here so loadStreetData never fetches them. tsid -> { row, data }.
 * @type {Map<string, { row: object, data: object }>}
 */
const draftStreets = new Map();

/** @type {null | { default: string, streets: Record<string, { label: string, file: string, hubId?: string }> }} */
let loadedIndex = null;

/**
 * LEVEL BUILDER published zones (spec 11, 15 Q6; js/zone-streets.js): solo only. On a multiplayer
 * page the zones' index rows are dropped and so is every arm that leads into a zone, so no way in
 * shows and nothing can travel there. Read once, from the page's mode.
 */
let zonesShown = isSolo(resolveGameMode());

/** Tests: show or hide the published zones' streets (the page's mode decides otherwise). */
export function setZoneStreetsShown(shown) {
  zonesShown = Boolean(shown);
}

/**
 * Fallback bootstrap index (used before async index load / offline tests).
 * Full catalog is assets/streets/index.json after import.
 */
export const STREET_INDEX = {
  default: 'GLI2V0UN7RD1T2J',
  streets: {
    GLI2V0UN7RD1T2J: {
      label: 'Hechey Track',
      file: 'assets/streets/GLI2V0UN7RD1T2J.json',
    },
    GLI3272LOTD1B1F: {
      label: 'Groddle Forest Junction',
      file: 'assets/streets/GLI3272LOTD1B1F.json',
    },
  },
};

/**
 * Merge generated index into STREET_INDEX (mutates export for game code).
 * @param {{ default?: string, streets?: Record<string, object> }} idx
 */
export function applyStreetIndex(idx) {
  if (!idx?.streets) return STREET_INDEX;
  loadedIndex = idx;
  if (idx.default) STREET_INDEX.default = idx.default;
  STREET_INDEX.streets = zonesShown ? { ...idx.streets } : withoutZoneRows(idx.streets);
  for (const [tsid, d] of draftStreets) STREET_INDEX.streets[tsid] = d.row;
  return STREET_INDEX;
}

/**
 * LEVEL BUILDER (spec 6.8): register a draft's streets for a play-test. `rows` are index rows by
 * tsid (label, hubId, hubName, ...; no file), `streetsByTsid` their street JSON. The rows join the
 * index (a later index load keeps them) and the streets prime the cache, so loadStreetData returns
 * them without a fetch. Each street is checked as a loaded file is (assertStreetGeometry) and copied,
 * so the caller's object is never changed. Returns the registered tsids.
 * @param {Record<string, object>} rows
 * @param {Record<string, object>} streetsByTsid
 */
export function registerDraftStreets(rows, streetsByTsid) {
  const out = [];
  for (const [tsid, street] of Object.entries(streetsByTsid || {})) {
    if (!street || typeof street !== 'object') continue;
    const data = typeof structuredClone === 'function' ? structuredClone(street) : JSON.parse(JSON.stringify(street));
    assertStreetGeometry(data);
    const row = { label: data.label || tsid, ...(rows?.[tsid] || {}), draft: true };
    delete row.file;
    applyIndexHub(data, row);
    data.signposts = navigableSignposts(data.signposts);
    draftStreets.set(tsid, { row, data });
    STREET_INDEX.streets[tsid] = row;
    cache.set(tsid, data);
    out.push(tsid);
  }
  return out;
}

/** Whether a tsid is a registered draft street (a play-test). */
export function isDraftStreet(tsid) {
  return draftStreets.has(tsid);
}

/**
 * Load assets/streets/index.json (browser) or return already-applied index.
 */
export async function ensureStreetIndex(fetchImpl = globalThis.fetch) {
  if (loadedIndex?.streets && Object.keys(STREET_INDEX.streets).length > 2) {
    return STREET_INDEX;
  }
  if (typeof fetchImpl !== 'function') return STREET_INDEX;
  try {
    const res = await fetchImpl('assets/streets/index.json');
    if (res.ok) {
      const idx = await res.json();
      applyStreetIndex(idx);
    }
  } catch {
    /* keep bootstrap */
  }
  return STREET_INDEX;
}

/**
 * Sync apply index from parsed object (tests / Node).
 * @param {object} idx
 */
export function loadStreetIndexObject(idx) {
  return applyStreetIndex(idx);
}

export function availableStreetTsids() {
  return Object.keys(STREET_INDEX.streets);
}

/**
 * Resolve a tsid (or alias) to a key present in the index.
 * @param {string} tsid
 */
export function resolveIndexTsid(tsid) {
  if (!tsid) return STREET_INDEX.default;
  if (tsid in STREET_INDEX.streets) return tsid;
  const aliases = [];
  if (tsid.startsWith('L')) aliases.push('G' + tsid.slice(1));
  if (tsid.startsWith('G')) aliases.push('L' + tsid.slice(1));
  if (tsid.startsWith('LLI')) aliases.push('GLI' + tsid.slice(3));
  if (tsid.startsWith('GLI')) aliases.push('LLI' + tsid.slice(3));
  for (const a of aliases) {
    if (a in STREET_INDEX.streets) return a;
  }
  return null;
}

/**
 * Street JSON written outside import-locations-xml.mjs (the Jethimadh Tower
 * Base corridors and rebuilt rooms, Towers basements, puzzle and party
 * streets: 64 files) carries no hubId/hubName, so the location chip fell back
 * to "Groddle Forest". The index row has the hub from inc_data_maps_prod.js;
 * fill whichever the JSON lacks (a JSON value always wins).
 * @param {object} data street JSON (mutated)
 * @param {{ hubId?: string, hubName?: string }|undefined} meta its index row
 */
export function applyIndexHub(data, meta) {
  if (!data || !meta) return data;
  if ((data.hubId == null || data.hubId === '') && meta.hubId != null && meta.hubId !== '') data.hubId = String(meta.hubId);
  if (!data.hubName && meta.hubName) data.hubName = meta.hubName;
  return data;
}

/**
 * @param {string} tsid
 */
export async function loadStreetData(tsid) {
  await ensureStreetIndex();
  const key = resolveIndexTsid(tsid) || STREET_INDEX.default;
  if (cache.has(key)) return cache.get(key);
  // A draft street (a play-test) is never a file: it comes back from its registration.
  if (draftStreets.has(key)) {
    const data = draftStreets.get(key).data;
    cache.set(key, data);
    return data;
  }
  const meta = STREET_INDEX.streets[key];
  if (!meta) throw new Error(`Unknown street tsid: ${tsid}`);
  const res = await fetch(meta.file);
  if (!res.ok) throw new Error(`Failed to load street ${key}: HTTP ${res.status}`);
  const data = await res.json();
  assertStreetGeometry(data);
  applyIndexHub(data, meta);
  // Hidden signpost connects stay in the JSON (source data) but never show.
  data.signposts = navigableSignposts(zonesShown ? data.signposts : withoutZoneConnects(data.signposts));
  cache.set(key, data);
  return data;
}

/**
 * Sync load for tests (Node) via fs — not used in browser.
 * @param {string} tsid
 * @param {string} baseDir absolute path to assets/streets
 */
export async function loadStreetDataFromFs(tsid, baseDir) {
  const { readFile } = await import('node:fs/promises');
  const { join } = await import('node:path');
  // Prefer applied index; if only bootstrap, try loading index.json from baseDir
  if (Object.keys(STREET_INDEX.streets).length <= 2) {
    try {
      const idx = JSON.parse(await readFile(join(baseDir, 'index.json'), 'utf8'));
      applyStreetIndex(idx);
    } catch {
      /* */
    }
  }
  const key = resolveIndexTsid(tsid) || STREET_INDEX.default;
  const meta = STREET_INDEX.streets[key];
  if (!meta) throw new Error(`Unknown street tsid: ${tsid}`);
  const rel = meta.file.replace(/^assets\/streets\//, '');
  const path = join(baseDir, rel);
  const data = JSON.parse(await readFile(path, 'utf8'));
  assertStreetGeometry(data);
  applyIndexHub(data, meta);
  data.signposts = navigableSignposts(zonesShown ? data.signposts : withoutZoneConnects(data.signposts));
  cache.set(key, data);
  return data;
}

export function clearStreetCache() {
  cache.clear();
}

export function clearStreetIndex() {
  loadedIndex = null;
  draftStreets.clear();
  STREET_INDEX.default = 'GLI2V0UN7RD1T2J';
  STREET_INDEX.streets = {
    GLI2V0UN7RD1T2J: {
      label: 'Hechey Track',
      file: 'assets/streets/GLI2V0UN7RD1T2J.json',
    },
    GLI3272LOTD1B1F: {
      label: 'Groddle Forest Junction',
      file: 'assets/streets/GLI3272LOTD1B1F.json',
    },
  };
}
